-- Reviewed Hadiqa menu import; no billing, offers, loyalty or customer mutations
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE hadiqa_before ON COMMIT DROP AS SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) snapshot;
DO $identity$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='26d964ab-7435-45e3-b721-536746dfcf12' AND slug='brand-dcf7296f722c' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Hadiqa brand identity changed';END IF;END $identity$;
CREATE TEMP TABLE hadiqa_expected_categories ON COMMIT DROP AS SELECT * FROM public.menu_categories WITH NO DATA;
DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12') AND (EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12' EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM hadiqa_expected_categories) OR EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM hadiqa_expected_categories EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12')) THEN RAISE EXCEPTION 'Existing categories differ; preserve owner changes';END IF;END $catalog$;
CREATE TEMP TABLE hadiqa_expected_products ON COMMIT DROP AS SELECT * FROM public.menu_products WITH NO DATA;
صورة توضيحية',35,'{}',NULL,4,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/c6125755-4dab-466a-8d40-4de8972a9d13/hadiqa-20261102-3601bf83fd5e33ee.webp','{}','{}'::jsonb);
صورة توضيحية',39,'{}',NULL,5,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/789f5b24-badd-428c-893b-fbbc4ca6bd65/hadiqa-20261102-91c9d3a09747c6e4.webp','{}','{}'::jsonb);
صورة توضيحية',35,'{}',NULL,6,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/e3c0cef8-fbdc-4ba3-86a9-a5c0ebabeb2a/hadiqa-20261102-97ba3974132a1ad5.webp','{}','{}'::jsonb);
للتعرف على مكونات وجبة الحديقة اسأل فريق المطعم',50,'{}',635,7,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/31eebbfa-a113-4fc6-837b-116075dc4313/hadiqa-20261102-9641ad9ab71174c0.webp','{}','{}'::jsonb);
صورة توضيحية',10,'{}',NULL,11,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/695d0ad6-cfb7-4c96-8ddc-b8da2945c151/hadiqa-20261102-be242ec44c7e8d10.webp','{}','{}'::jsonb);
صورة توضيحية',3,'{}',NULL,12,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/8acfe26f-8172-44dd-8a05-06692a4c18f2/hadiqa-20261102-101e731c873afd44.webp','{}','{}'::jsonb);
صورة توضيحية',3,'{}',NULL,13,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/287bd5d0-e900-48c6-8732-2b34ef025019/hadiqa-20261102-85037952d0357e70.webp','{}','{}'::jsonb);
صورة توضيحية',3,'{}',NULL,14,true,'product','26d964ab-7435-45e3-b721-536746dfcf12/87ad8350-c6e8-4171-85d8-99412ca0a6e6/hadiqa-20261102-d4a00a82f2be3661.webp','{}','{}'::jsonb);
DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12') AND (EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12' EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM hadiqa_expected_products) OR EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM hadiqa_expected_products EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12')) THEN RAISE EXCEPTION 'Existing products differ; preserve owner changes';END IF;END $catalog$;
DO $logo$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12') THEN RAISE EXCEPTION 'Hadiqa settings missing';END IF;IF EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12' AND ((logo_storage_path IS NOT NULL AND logo_storage_path IS DISTINCT FROM '26d964ab-7435-45e3-b721-536746dfcf12/identity/hadiqa-20261102-6c424e210dcac1f5.webp') OR logo_url IS NOT NULL)) OR EXISTS(SELECT 1 FROM public.cafe_custom_identity WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12' AND (logo_storage_path IS DISTINCT FROM '26d964ab-7435-45e3-b721-536746dfcf12/identity/hadiqa-20261102-6c424e210dcac1f5.webp' OR logo_url IS NOT NULL OR palette IS DISTINCT FROM '{"primary":"#171D2B","secondary":"#FCF5E8","accent":"#DDB35C","background":"#171D2B","text":"#FCF5E8"}'::jsonb)) THEN RAISE EXCEPTION 'Existing Hadiqa identity differs; preserve owner changes';END IF;END $logo$;
UPDATE public.cafe_settings SET logo_storage_path='26d964ab-7435-45e3-b721-536746dfcf12/identity/hadiqa-20261102-6c424e210dcac1f5.webp',updated_at=now() WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12' AND logo_storage_path IS DISTINCT FROM '26d964ab-7435-45e3-b721-536746dfcf12/identity/hadiqa-20261102-6c424e210dcac1f5.webp';
DO $verify$ DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'26d964ab-7435-45e3-b721-536746dfcf12'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) INTO actual;IF actual IS DISTINCT FROM(SELECT snapshot FROM hadiqa_before) THEN RAISE EXCEPTION 'Protected brands, loyalty, billing or customer data changed';END IF;IF(SELECT count(*) FROM public.menu_products WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12' AND available AND price>0)<>16 OR(SELECT count(*) FROM public.menu_categories WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12')<>4 OR(SELECT sum(coalesce(jsonb_array_length(commerce_details->'options'),0)) FROM public.menu_products WHERE cafe_id='26d964ab-7435-45e3-b721-536746dfcf12')<>0 THEN RAISE EXCEPTION 'Hadiqa count, prices or media mismatch';END IF;END $verify$;
COMMIT;
